import { forwardRef, type HTMLAttributes, type ReactElement, type ReactNode } from "react";

import { cn } from "@/lib/cn";

export type BadgeVariant = "selected" | "unselected" | "success" | "danger";
export type BadgeSize = "md" | "sm";
export type BadgeShape = "pill" | "rounded";

/**
 * Both sizes share a 12px label and the same padding — the sheet draws them
 * that way. The difference is height: 22px and 28px.
 *
 * The sheet reaches those heights by inflating the md line-height to 145%,
 * which is off the leading scale (flat/tight/snug/normal/relaxed) and makes a
 * control's height depend on font metrics. Pinning `min-h` instead lands on the
 * designed numbers exactly, keeps `leading-flat` for both, and survives a font
 * swap. The padding scale cannot express it: py-xs gives 22px and py-sm 30px.
 *
 * These were previously identical apart from the icon, so a badge with no icon
 * rendered the same at both sizes.
 */
const SIZE = {
  md: "gap-xs px-sm py-xs text-label-sm min-h-7 [&_svg]:size-4",
  sm: "gap-xs px-sm py-xs text-label-sm min-h-5.5 [&_svg]:size-3",
} as const satisfies Record<BadgeSize, string>;

/**
 * The status variants carry no border in the design: their tint alone
 * separates them from the page, which is what makes a row of them read as
 * data rather than as controls.
 */
const VARIANT = {
  selected: "bg-accent border-accent text-ink-on-accent",
  unselected: "bg-base border-edge-subtle text-ink-muted",
  success: "bg-success-subtle border-transparent text-success",
  danger: "bg-danger-subtle border-transparent text-ink-on-danger-subtle",
} as const satisfies Record<BadgeVariant, string>;

/**
 * Interaction props are removed from the type, not merely discouraged in the
 * docs. Badge renders a `<span>`: an `onClick` there has no role, no focus and
 * no keyboard path, and a `tabIndex` invents a tab stop that announces
 * nothing. The doc said "don't" while the types said "go ahead" — the same
 * doc/type disagreement caught once before, so it graduates to a type.
 * Interactivity belongs in `iconEnd`, or wrap the badge in a real control.
 */
type FakeInteractionProps =
  | "onClick"
  | "onDoubleClick"
  | "onMouseDown"
  | "onMouseUp"
  | "onKeyDown"
  | "onKeyUp"
  | "tabIndex";

export interface BadgeProps extends Omit<HTMLAttributes<HTMLSpanElement>, FakeInteractionProps> {
  variant?: BadgeVariant;
  size?: BadgeSize;
  shape?: BadgeShape;
  /** Slot: trailing mark — an external-link arrow, a check, a remove glyph. */
  iconEnd?: ReactElement;
  children: ReactNode;
}

/**
 * A label, not a control.
 *
 * Badge renders a `<span>` and takes no interaction props. The sheet draws
 * variants carrying a `×` or a check, which look like buttons — those are
 * *slots*: pass a real `<button>` with its own accessible name into `iconEnd`.
 * Making the badge itself clickable would give a non-interactive element a
 * click handler with no role, no focus and no keyboard path, which is the most
 * common accessibility defect in tag components.
 */
export const Badge = forwardRef<HTMLSpanElement, BadgeProps>(function Badge(
  { variant = "unselected", size = "sm", shape = "pill", iconEnd, className, children, ...rest },
  ref,
) {
  return (
    <span
      ref={ref}
      data-slot="badge"
      data-variant={variant}
      data-size={size}
      className={cn(
        "inline-flex w-fit shrink-0 items-center border-[1.5px]",
        "font-body font-bold leading-flat tracking-tight whitespace-nowrap",
        shape === "pill" ? "rounded-full" : "rounded-sm",
        SIZE[size],
        VARIANT[variant],
        className,
      )}
      {...rest}
    >
      {children}
      {iconEnd}
    </span>
  );
});

/** Typed documentation for Badge (CONVENTIONS §11). */

export const badgeDoc = {
  name: "Badge",
  status: "stable",
  summary: "A short status or selection label. Four variants, two sizes, pill or rounded, with an optional trailing slot.",

  anatomy: [
    { part: "root", slot: "badge", notes: "A <span>. Carries data-variant and data-size." },
    { part: "label", slot: null, notes: "children." },
    { part: "iconEnd", slot: null, notes: "Trailing mark. Pass a real <button> here when it should be actionable." },
  ],

  composition: `
Badge
├─ children   ReactNode — the label
└─ iconEnd?   ReactElement — arrow, check, or a real <button> for remove
  `.trim(),

  props: {
    variant: {
      type: '"selected" | "unselected" | "success" | "danger"',
      default: '"unselected"',
      notes: "selected is the brand fill; unselected is outlined; success and danger are tinted status labels with no border, so a row of them reads as data rather than controls.",
    },
    size: {
      type: '"md" | "sm"',
      default: '"sm"',
      notes:
        "22px and 28px tall. Both carry the same 12px label and the same padding — the difference is height alone, pinned with min-h because the spacing scale cannot express 28 (py-xs gives 22, py-sm 30). md pairs with a 16px icon, sm with 12px. These two were previously identical apart from the icon, so a badge with no icon rendered the same at either size.",
    },
    shape: { type: '"pill" | "rounded"', default: '"pill"' },
    iconEnd: { type: "ReactElement", notes: "Slot. A decorative mark should be aria-hidden; an interactive one must be a real button with its own accessible name." },
  },

  do: [
    "Keep the label to one or two words — a badge is a label, not a sentence.",
    "Pass a real <button aria-label=\"Remove X\"> into iconEnd for removable tags.",
    "Use success/danger for state, selected/unselected for choice; do not mix the meanings.",
  ],

  dont: [
    "Do not try to make the Badge itself interactive — onClick, onKeyDown and tabIndex are removed from the prop type, because a click handler on a <span> has no role, no focus and no keyboard path. Put the control in iconEnd, or wrap the badge in a real button.",
    "Do not use a badge as a button substitute for primary actions.",
    "Do not convey status by colour alone — the label carries the meaning (WCAG 1.4.1).",
  ],

  a11y: {
    role: "none (plain text). Deliberate: a label with no interaction should not claim one — and the prop type removes the interaction handlers so it cannot acquire one by accident.",
    keyboard: [{ key: "—", does: "Not focusable. Interactivity lives in the iconEnd slot's own control." }],
    contrast: "Measured in both schemes. Light: selected 11.4:1, unselected 5.9:1, success 5.1:1, danger 8.5:1. Dark: 11.4 / 4.9 / 5.7 / 5.9:1.",
  },

  knownGaps: [
    "No dedicated removable-tag component. The sheet draws a `×` variant; today that is composed by passing a button into iconEnd, which keeps the accessible name at the call site where it belongs.",
    "No hover or focus treatment — Badge is not interactive, so it has neither by design.",
  ],

  design: "https://app.paper.design/file/01KZ39A2BC286MT85M658NRR4R/4-0",
} as const;

export type BadgeDoc = typeof badgeDoc;
